func totalsByOperatorAM(day vaccexecapp.DrivePlanDay) map[string]int {
	totals := map[string]int{}
	for _, assignment := range day.Assignments {
		totals[assignment.OperatorName] += assignment.Animals
	}
	return totals
}

func assignmentForAM(day vaccexecapp.DrivePlanDay, operator, shed string) int {
	for _, assignment := range day.Assignments {
		if assignment.OperatorName == operator && assignment.PhysicalShed == shed {
			return assignment.Animals
		}
	}
	return 0
}

func hasWarningAM(day vaccexecapp.DrivePlanDay, warning string) bool {
	for _, assignment := range day.Assignments {
		for _, got := range assignment.Warnings {
			if got == warning {
				return true
			}
		}
	}
	return false
}

func planTextContainsAM(plan vaccexecapp.DrivePlan, needle string) bool {
	needle = strings.ToLower(needle)
	for _, warning := range plan.Warnings {
		if strings.Contains(strings.ToLower(warning), needle) {
			return true
		}
	}
	for _, day := range plan.Days {
		for _, assignment := range day.Assignments {
			for _, warning := range assignment.Warnings {
				if strings.Contains(strings.ToLower(warning), needle) {
					return true
				}
			}
		}
	}
	return false
}

func dateAM(year int, month time.Month, day int) time.Time {
	return time.Date(year, month, day, 0, 0, 0, 0, time.UTC)
}
